const VOICE_DATA = {"file":"voice/ep04.mp3","lines":{"ep04_001":{"who":"TAKUTO","text":"Previously. I passed the Hunters' exam, with Rin and a guy whose head is on fire.","mono":true,"off":0.25,"dur":5.227,"env":"0117774256984431331100000003760254677643118214764034532342122255554321100000033111247777654321345321156666644331133231135652432344331000655432111000000000000"},"ep04_002":{"who":"TAKUTO","text":"Wick told me nobody has ever gone home. Not one. Not ever.","mono":true,"off":5.8767,"dur":3.755,"env":"01399100255772455555557215523344453034313311344433311455321000000000000024688511344333334444433453111100000000000"},"ep04_003":{"who":"TAKUTO","text":"We killed a Greater Fiend that should never have been there. Somebody herded it to us.","mono":true,"off":10.0313,"dur":4.885,"env":"014410222999988515521115667364111024454433322133124342144556414434421014444433322111000000000000134896547864432114776353232003223223100122210000000"},"ep04_004":{"who":"TAKUTO","text":"And the axe keeps saying one word. Static.","mono":true,"off":15.3167,"dur":2.645,"env":"04567634688503301253233375554455566555555543321110000000133119877522100000000000"},"ep04_005":{"who":"VALENTINE","text":"Gideon. It is midnight. Even your gears should be asleep.","mono":false,"off":18.362,"dur":3.179,"env":"149925555544310342343316676400344322101000000002564256665542012555443223312002322341233210000000"},"ep04_006":{"who":"GIDEON","text":"Gears never sleep, Valentine. They only wait to be useful.","mono":false,"off":21.9407,"dur":3.989,"env":"025787642125663132222221135421000000000012776533332111332110000000000000025679986665323655320011211322212343122101110000"},"ep04_007":{"who":"VALENTINE","text":"What are you building?","mono":false,"off":26.33,"dur":1.344,"env":"02795477546740287765235333310000000000000"},"ep04_008":{"who":"GIDEON","text":"A problem. A boy with an axe that breaks everything and protects nothing.","mono":false,"off":28.074,"dur":4.544,"env":"02200116887751122110000000000000144318999986543244254433554310022103310035542022002562133100122100000000004421220224310022044311112110000"},"ep04_009":{"who":"VALENTINE","text":"Our little error. Sieg told you about the block?","mono":false,"off":33.018,"dur":2.645,"env":"05898889487503777655433310013554774104337786135640653004205666543210010000000000"},"ep04_010":{"who":"GIDEON","text":"Sieg told me the boy took a hit from a Behemoth trying to block with it. Any other Hunter would be soup.","mono":false,"off":36.0633,"dur":5.952,"env":"01338963202269974466526321289996532022312321016730000001466314311114665433221000000015764313320256655310013201100000000000000000057998899336421226764121222112320132122223321000000"},"ep04_011":{"who":"GIDEON","text":"You cannot change what a Brand is, Valentine. But you can change what holds it.","mono":false,"off":42.4153,"dur":5.163,"env":"03514696998753000122246654333211103524320057666543331233211011000000014766433331112321100000000000000000312463126641222366643332111003420113875431121100000"},"ep04_012":{"who":"VALENTINE","text":"Gears and chains for a three hundred year old curse. You are a romantic.","mono":false,"off":47.978,"dur":3.925,"env":"0157887665342465165155555443410143100125552255524213444443210011444221123200000000000467997742666545555554020211000000"},"ep04_013":{"who":"GIDEON","text":"I am an engineer. It is the same thing with more burns.","mono":false,"off":52.3033,"dur":3.605,"env":"1499988887654555767652334544321000000000000000274995311443338998642111687432222441057876531028865321000110000"},"ep04_014":{"who":"CLERK","text":"Good morning, Hunters! Your first official quests!","mono":false,"off":56.3087,"dur":2.368,"env":"066468988876643477621565554112454100177651034006411630014643311000000000"},"ep04_015":{"who":"WICK","text":"Our first quest! What is it? A dragon? A cursed castle?","mono":false,"off":59.0767,"dur":2.731,"env":"0551069953014987531024775885466511343257776534665213301247763210146552322211000000"},"ep04_016":{"who":"CLERK","text":"Rats in the bakery cellar.","mono":false,"off":62.2073,"dur":1.259,"env":"05775012778429872015554111554333222100"},"ep04_017":{"who":"WICK","text":"...Rats.","mono":false,"off":63.866,"dur":0.576,"env":"026998777412220000"},"ep04_018":{"who":"CLERK","text":"Very large rats. Rank F large.","mono":false,"off":64.842,"dur":1.984,"env":"079778977888886123576554201200277763167400246655443320011000"},"ep04_019":{"who":"SIEG","text":"Not you, Takuto. You have a different appointment.","mono":false,"off":67.226,"dur":3.221,"env":"1886654112577666665302287664011987432776654443100000000799996477548521665773012777741134332231000"},"ep04_020":{"who":"TAKUTO","text":"With who?","mono":false,"off":70.8473,"dur":0.747,"env":"02561222899854321000000"},"ep04_021":{"who":"SIEG","text":"Gideon Halloway. The Guild artificer. He builds things for Hunters who can't survive without them.","mono":false,"off":71.994,"dur":5.973,"env":"059756666555563356555665554444300000000000775369765653104665546621165432643320000000000098668655433104656555310565237555225655432175201776422332775465545554225644665410003322100000"},"ep04_022":{"who":"TAKUTO","text":"You think I can't survive?","mono":false,"off":78.3673,"dur":1.472,"env":"014521975798201376532535326776532110000000000"},"ep04_023":{"who":"SIEG","text":"I watched you try to block a rock the size of a house with an axe that refuses to block.","mono":false,"off":80.2393,"dur":5.397,"env":"289887655422303864338656662575377555300676667655530001763326655566646745553376654333321000000000079797412565420033201751058741017877645655420016842776543210000000"},"ep04_024":{"who":"RIN","text":"Twice.","mono":false,"off":86.0367,"dur":0.661,"env":"01399988852221110000"},"ep04_025":{"who":"TAKUTO","text":"Once was a reflex.","mono":false,"off":87.098,"dur":1.323,"env":"0149986230484485335553110343100011100000"},"ep04_026":{"who":"RIN","text":"And the second time?","mono":false,"off":88.8207,"dur":1.173,"env":"058873336950166522255554433320000000"},"ep04_027":{"who":"TAKUTO","text":"...Also a reflex.","mono":false,"off":90.394,"dur":1.259,"env":"00489843368775346653112443100111000000"},"ep04_028":{"who":"SIEG","text":"Gideon is a genius. He is also strange. Don't touch anything that ticks.","mono":false,"off":92.0527,"dur":4.821,"env":"0698566665554203765775544577666765443322100000008988656555542247664232017766665544433200000000007875312595213126777625667656630001288420023221000"},"ep04_029":{"who":"WICK","text":"Can I come? I want to see a genius! I've only ever seen regular people!","mono":false,"off":97.274,"dur":3.904,"env":"0188898720259865432788747895444434775223577664322133210000006853887877226844753442666765587424645410144301322100000000"},"ep04_030":{"who":"SIEG","text":"You have rats.","mono":false,"off":101.578,"dur":1.109,"env":"0898999876567877766653113222100000"},"ep04_031":{"who":"WICK","text":"I have rats.","mono":false,"off":103.0873,"dur":0.853,"env":"26788984469986542022210000"},"ep04_032":{"who":"RIN","text":"I'll go with Takuto. Someone has to make sure he doesn't touch anything that ticks.","mono":false,"off":104.3407,"dur":4.523,"env":"0467852299997588100225675111564021454433210000001339877875466330257766302334645525763354111354013114566400444434431011343100122210000000"},"ep04_033":{"who":"WICK","text":"Hey! Why does she get the genius and I get the rats?","mono":false,"off":109.2633,"dur":2.432,"env":"0277777536986485332525830253222566664443312456542164004446543210122100000"},"ep04_034":{"who":"SIEG","text":"Because she's rank C, and you set the last cellar on fire.","mono":false,"off":112.0953,"dur":3.563,"env":"07626965432666545666555312222166554332000000000068877522553000666555445310124755555554455310365444322110000"},"ep04_035":{"who":"GIDEON","text":"Ah! The error! Come in, come in. Don't touch anything that ticks.","mono":false,"off":116.058,"dur":3.925,"env":"0158987643312441246753311100000000029898875531225875443210000000000001897410225610222567631023443343200012253100121000"},"ep04_036":{"who":"TAKUTO","text":"Sieg said that.","mono":false,"off":120.3833,"dur":1.045,"env":"00116631221997222554321000000000"},"ep04_037":{"who":"GIDEON","text":"Sieg learned it the hard way. Ask him about his eyebrows sometime.","mono":false,"off":121.8287,"dur":4.032,"env":"0123885212558998541331000211111476533200243221000000000000000048853311446533553213322002455420232211111122443211122100000"},"ep04_038":{"who":"RIN","text":"Is that why he wears the headband?","mono":false,"off":126.2607,"dur":1.792,"env":"055409752146778786216536876644205324652015433321100000"},"ep04_039":{"who":"GIDEON","text":"I could not possibly say.","mono":false,"off":128.4527,"dur":1.557,"env":"03782229937998650000115852223311332222442110000"},"ep04_040":{"who":"GIDEON","text":"Arms out, boy. Let me see how you hold it.","mono":false,"off":130.41,"dur":2.731,"env":"0268998777633766432000045432111000000000000683465333354322565433331137743112100000"},"ep04_041":{"who":"TAKUTO","text":"Like this?","mono":false,"off":133.5407,"dur":0.875,"env":"003798521149974211110000000"},"ep04_042":{"who":"GIDEON","text":"Like a man carrying a plank. Wonderful. Terrible. Wonderful.","mono":false,"off":134.8153,"dur":4.032,"env":"0157612757766554433021357544333330011454322010000000000024799863421112200000000021468755201110000000000256544222111211000"},"ep04_043":{"who":"GIDEON","text":"Here is your problem. Ruinbreaker refuses to defend. When you raise it to block, the Brand lets go of your hands.","mono":false,"off":139.2473,"dur":7.381,"env":"001588744541112443000004553310011000000000000000024799886641454201233223110010344312121200121221112553211000000000000000003666653237776542222200122103465421100000000000033201566554323112321022003454431123211134421100011000"},"ep04_044":{"who":"TAKUTO","text":"That's what it felt like. Like it slid out of my grip on purpose.","mono":false,"off":147.0287,"dur":3.84,"env":"00367613313896840111498762023322110000000000015651261144431458877766542455443214652024443211266510221012221000000000"},"ep04_045":{"who":"GIDEON","text":"On purpose is exactly right. A Brand is a will, boy. Yours has opinions.","mono":false,"off":151.2687,"dur":5.483,"env":"037761116972012122122234212266420011333244321100000000000000033149987766552332344321367764221110001666532110000000000000002489875322111211332132000046433211000010000"},"ep04_046":{"who":"AKURO","text":"Opinions. Ha. I like this old man.","mono":true,"off":157.1513,"dur":2.517,"env":"0157301477877576665432221247987334666567642012664431245664113655433221110000"},"ep04_047":{"who":"GIDEON","text":"So we do not ask the Brand to block. We ask the metal.","mono":false,"off":160.0687,"dur":3.328,"env":"0138777427889987511003554221001430267644332113202576532100000000000000014566753222100245443201100000"},"ep04_048":{"who":"RIN","text":"What does that mean?","mono":false,"off":163.7967,"dur":1.067,"env":"04714744198630467665444332000000"},"ep04_049":{"who":"GIDEON","text":"My Brand, Cogwheel Core. Anything metal I touch becomes a machine that obeys me.","mono":false,"off":165.2633,"dur":5.568,"env":"024553015887653221110000001356542001332100113321000000000000000000599962146566777623433333210113430001100000031236543343543221112432322121221112455310444332222011100000"},"ep04_050":{"who":"GIDEON","text":"A chain harness, wound into the haft. When something strikes at you, the chains lock the axe crossways, all by themselves.","mono":false,"off":171.2313,"dur":8.085,"env":"023013336798775432367643221011000000001347997544331344132342113553210000000000000000000005774333598520144421210376641012232011221100000000001410233377765434321156664200003421344300120001377512210222111010000004676521444442133321224432110000000"},"ep04_051":{"who":"TAKUTO","text":"So the axe can block.","mono":false,"off":179.7167,"dur":1.429,"env":"0136966864578850340167653568975210000000000"},"ep04_052":{"who":"GIDEON","text":"Once.","mono":false,"off":181.546,"dur":0.661,"env":"02489875333122210000"},"ep04_053":{"who":"TAKUTO","text":"Once?","mono":false,"off":182.6073,"dur":0.661,"env":"01369985431211100000"},"ep04_054":{"who":"GIDEON","text":"Once. After that the Brand notices what we did and snaps the chains like threads. No offense, young lady.","mono":false,"off":183.6687,"dur":7.168,"env":"026996321210000000037962016635664013203777655454566641311123210354023320266543200000000000353333146653001100410122145533332220233310000015642210001000000000000000000478998731101365321011000000024663333333332111100000"},"ep04_055":{"who":"RIN","text":"Some offense.","mono":false,"off":191.2367,"dur":0.917,"env":"0148899951068765411111000000"},"ep04_056":{"who":"GIDEON","text":"Then I rewind them. That takes a night. One block per day, boy. Spend it wisely.","mono":false,"off":192.554,"dur":5.376,"env":"025756655653554355554433111100000000000000145202245313333544332100000000000000158988732678764100002443114443332003433211100000000130077533300123454433312211100000"},"ep04_057":{"who":"TAKUTO","text":"One block a day.","mono":false,"off":198.33,"dur":1.152,"env":"01477766336997401521565321100000000"},"ep04_058":{"who":"GIDEON","text":"It is one more than you have now.","mono":false,"off":199.882,"dur":1.92,"env":"0378586341237996655577531100000034443222365111123211000000"},"ep04_059":{"who":"RIN","text":"Why are you helping him? The Guild doesn't pay you for this.","mono":false,"off":202.202,"dur":2.88,"env":"037877777556422477400354432444432000006310398876621037534531113554434411133142112332000"},"ep04_060":{"who":"GIDEON","text":"Because thirty years ago a boy with a broken Brand came into this forge, and I told him there was nothing I could do.","mono":false,"off":205.482,"dur":7.04,"env":"03237843210006898354334664223213444333210067787432221231332001578720012333202565432211100000356545422221231221000344321000100000000000000358875102136764112221000000000003653432256852111322212220012310012321000000"},"ep04_061":{"who":"RIN","text":"What happened to him?","mono":false,"off":212.922,"dur":1.195,"env":"059812368620677543653356544432000000"},"ep04_062":{"who":"GIDEON","text":"He believed me.","mono":false,"off":214.5167,"dur":1.109,"env":"0059616955557754332211010221100000"},"ep04_063":{"who":"GIDEON","text":"I have not said those words since. Arms out again, boy.","mono":false,"off":216.026,"dur":3.797,"env":"004667328976401222675200444421024433202222543201100000000000000369998875347776312421354432211100000006664321110000"},"ep04_064":{"who":"GIDEON","text":"Sieg! Swing at him. Properly. Not your polite swing.","mono":false,"off":220.2233,"dur":3.435,"env":"00225886531112222138966543111222000000000038984013222110000000000046731243011455544320011221254321100000"},"ep04_065":{"who":"SIEG","text":"I don't have a polite swing.","mono":false,"off":224.058,"dur":1.643,"env":"05985966557776557630697766664123331787754432210000"},"ep04_066":{"who":"TAKUTO","text":"He does. I've seen the other one.","mono":false,"off":226.1007,"dur":1.835,"env":"00332299986522100454123222454443445424432221100000000000"},"ep04_067":{"who":"SIEG","text":"Ready?","mono":false,"off":228.3353,"dur":1.003,"env":"0799886587765555421000000000000"},"ep04_068":{"who":"TAKUTO","text":"It blocked. It actually blocked!","mono":false,"off":229.738,"dur":1.749,"env":"15310589987630016455542144334442146665310000010000000"},"ep04_069":{"who":"GIDEON","text":"Of course it blocked. I built it.","mono":false,"off":231.8873,"dur":2.197,"env":"045300226999632224410056976431100010000000004664205875311222100000"},"ep04_070":{"who":"SIEG","text":"Again.","mono":false,"off":234.4847,"dur":0.811,"env":"0499888878787666654100000"},"ep04_071":{"who":"TAKUTO","text":"Wait, he said only once...","mono":false,"off":235.6953,"dur":1.579,"env":"015799510145332986565544544356642100221100000000"},"ep04_072":{"who":"TAKUTO","text":"Ow.","mono":false,"off":237.674,"dur":0.555,"env":"04689987532000000"},"ep04_073":{"who":"GIDEON","text":"Once! I said once! Nobody ever listens to the engineer!","mono":false,"off":238.6287,"dur":3.648,"env":"02699632111100013322122542111344211011000000000000047982362332025621543346321112211002223344333111222221100000"},"ep04_074":{"who":"RIN","text":"That was the best thing I've seen all week.","mono":false,"off":242.6767,"dur":2.091,"env":"067625731882697423101765544554133335665413556532454210010000000"},"ep04_075":{"who":"SIEG","text":"Good. Now you know exactly how much one block is worth. Spend it on someone else.","mono":false,"off":245.1673,"dur":4.843,"env":"07987542000266555666655554455476541003667546556654203204765554266555420066444566664332000000000000242068776674100367653324756665556543221122220000"},"ep04_076":{"who":"TAKUTO","text":"Someone else?","mono":false,"off":250.41,"dur":0.939,"env":"00159655656667532101110000000"},"ep04_077":{"who":"SIEG","text":"You can dodge for yourself. You can't dodge for the person standing behind you.","mono":false,"off":251.7487,"dur":4.587,"env":"069417977644754445544321066666653322476543210000000000002861279753101067545555433104745301976532266643202776664555535542475665542332210000"},"ep04_078":{"who":"TAKUTO","text":"...Yeah. That's what it's for.","mono":false,"off":256.7353,"dur":1.451,"env":"03479986432887414036745314110443221100000000"},"ep04_079":{"who":"WICK","text":"Quest complete! Rats defeated! Bakery mostly standing!","mono":false,"off":258.586,"dur":3.008,"env":"0199542027632387652123788730320351006644542210066511266555655432034333214444432211110000000"},"ep04_080":{"who":"CLERK","text":"Mostly?","mono":false,"off":261.994,"dur":0.704,"env":"0489875110256554320000"},"ep04_081":{"who":"NEMU","text":"The east wall is a little bit gone.","mono":false,"off":263.098,"dur":2.347,"env":"01220069863234120255543221000000000000055354365451363000355532110000000"},"ep04_082":{"who":"WICK","text":"The rats were very big! I panicked! My head panicked!","mono":false,"off":265.8447,"dur":2.581,"env":"054899843518633997777317987423356511257666431020157655467631115543221001200000"},"ep04_083":{"who":"CLERK","text":"Nemu, why are you covered in flour?","mono":false,"off":268.826,"dur":1.771,"env":"047677899875337766554420112531464453201155443221110000"},"ep04_084":{"who":"NEMU","text":"I took a nap in the flour sacks. It was very soft. Then the wall exploded.","mono":false,"off":270.9967,"dur":6.101,"env":"0022335026555655320000000575421103444322223212111000111100000000000000000001541544105544443232223332110000000200000000000000000000006998655420000045323455554322101222013343222110010000"},"ep04_085":{"who":"CLERK","text":"You came along to help?","mono":false,"off":277.498,"dur":1.109,"env":"0330149877667765454234554310000000"},"ep04_086":{"who":"NEMU","text":"I came along for the free bread. The baker gave us a reward. Burnt.","mono":false,"off":279.0073,"dur":5.056,"env":"01320322988876577776554311141342211565530344443211020000000000000000000000461099984022344200346673144644332564244432210002000000000000003799741000043000"},"ep04_087":{"who":"WICK","text":"He said it was a reward. He said it while crying.","mono":false,"off":284.4633,"dur":2.432,"env":"0544489859437747856985568887554210000564439947425762012776643221111000000"},"ep04_088":{"who":"CLERK","text":"I'll put down quest complete. With an asterisk.","mono":false,"off":287.2953,"dur":2.283,"env":"058402961888762138852101454214654420000374485455664211355432211100000"},"ep04_089":{"who":"WICK","text":"An asterisk! Like Takuto's star!","mono":false,"off":289.978,"dur":1.984,"env":"068888843159899430178630249972159712887643321766443221000000"},"ep04_090":{"who":"CLERK","text":"It is not like Takuto's star.","mono":false,"off":292.362,"dur":1.707,"env":"0869953799864587101167510385117776322117654433221000"},"ep04_091":{"who":"NEMU","text":"Where is Takuto?","mono":false,"off":294.4687,"dur":1.28,"env":"005988954421422886102165124153221000000"},"ep04_092":{"who":"CLERK","text":"At the forge with Gideon all day. And Rin. Rin volunteered.","mono":false,"off":296.1487,"dur":3.435,"env":"02005100599982214720006757875423766651145544332100006554467666443100000257766532776545542221254322210000"},"ep04_093":{"who":"NEMU","text":"Rin volunteered.","mono":false,"off":299.9833,"dur":1.259,"env":"00189966543001654434320441321100002000"},"ep04_094":{"who":"WICK","text":"Rin volunteered!","mono":false,"off":301.642,"dur":1.173,"env":"048767633998656552432544322110000000"},"ep04_095":{"who":"NEMU","text":"Interesting.","mono":false,"off":303.2153,"dur":0.896,"env":"049763311443222023221100000"},"ep04_096":{"who":"WICK","text":"They were the size of dogs. Dogs, Takuto. Dogs with teeth.","mono":false,"off":304.5113,"dur":3.307,"env":"0678959654787895674269887754221221000788887533302786312851267655432137767643322640023364211000000000"},"ep04_097":{"who":"TAKUTO","text":"Did you set the cellar on fire?","mono":false,"off":308.218,"dur":1.813,"env":"0132245333894014222676555444444100175654211100000000000"},"ep04_098":{"who":"WICK","text":"Only a little bit.","mono":false,"off":310.4313,"dur":1.045,"env":"06998999999698795378642013310000"},"ep04_099":{"who":"RIN","text":"The baker says the whole cellar.","mono":false,"off":311.8767,"dur":1.664,"env":"05317998401166532246532054125655422215443221110000"},"ep04_100":{"who":"WICK","text":"The baker exaggerates.","mono":false,"off":313.9407,"dur":1.451,"env":"04527999411888764444699874236554322102220000"},"ep04_101":{"who":"RIN","text":"What was that?!","mono":false,"off":315.7913,"dur":0.917,"env":"0586269742187554320121000000"},"ep04_102":{"who":"TAKUTO","text":"That came from the artisans' quarter.","mono":false,"off":317.1087,"dur":2.005,"env":"0059920024998875126565542479856454355340114887522210000000000"},"ep04_103":{"who":"RIN","text":"The forge. Gideon's forge!","mono":false,"off":319.514,"dur":1.621,"env":"0411159999988422310188467765431036655433201210000"},"ep04_104":{"who":"WICK","text":"Gideon! Where are you?","mono":false,"off":321.5353,"dur":1.109,"env":"0598487876664898887544433221100000"},"ep04_105":{"who":"GIDEON","text":"Here! Mind the floor! Mind the hole in the floor!","mono":false,"off":323.0447,"dur":2.88,"env":"003799742113566765532111113764321000000000000015775343111168743323343311111364321000000"},"ep04_106":{"who":"RIN","text":"That's a Rift. Inside a building.","mono":false,"off":326.3247,"dur":1.856,"env":"03651237535976411102000367744346556546206654314222200000"},"ep04_107":{"who":"TAKUTO","text":"Rifts open in the sky. Everyone keeps saying that.","mono":false,"off":328.5807,"dur":3.221,"env":"0148951223204786104544343323202556653111100000000157324644544210033112323433333322322110000000000"},"ep04_108":{"who":"WICK","text":"Shieldbearer! In the middle of town!","mono":false,"off":332.202,"dur":1.664,"env":"01337987424987776325777777466620416654322111000000"},"ep04_109":{"who":"GIDEON","text":"It came through the floor. Someone opened that. I felt it, like a key turning in a lock.","mono":false,"off":334.266,"dur":5.867,"env":"02313378876411115765213111125754321000000000000013499775543312565101233312331110000000000000014421111787410222100000000004551122001112332210002125665322222232343334443211000000"},"ep04_110":{"who":"TAKUTO","text":"Out of the way!","mono":false,"off":340.5327,"dur":0.96,"env":"05799695228649886322110000000"},"ep04_111":{"who":"RIN","text":"It's faster than the one in the canyon!","mono":false,"off":341.8927,"dur":1.856,"env":"04034108986241388457677537877676664021555555432221000000"},"ep04_112":{"who":"WICK","text":"The fire's spreading to the coal store! If that goes up, the whole street goes!","mono":false,"off":344.1487,"dur":3.776,"env":"041008987667764320068666652445502167665332115433323210000351058851057653675100542365542220265310154322112210000000"},"ep04_113":{"who":"RIN","text":"Wick, can you pull the fire back?","mono":false,"off":348.3247,"dur":1.621,"env":"0599300201478773011566354115555554215332100000000"},"ep04_114":{"who":"WICK","text":"I can tell my fire what to do! That fire isn't mine!","mono":false,"off":350.346,"dur":3.029,"env":"0551784739877877611298677774497005442367654322000007730111987667655455433665543221110000000"},"ep04_115":{"who":"GIDEON","text":"The bellows! Smash the bellows and it will starve of air!","mono":false,"off":353.7753,"dur":3.541,"env":"04431888756322111100000000002317987653211014315664232211110000000003463133222220055543331132121233211000000"},"ep04_116":{"who":"WICK","text":"Smashing things isn't my department!","mono":false,"off":357.7167,"dur":1.877,"env":"021899954388830797777532266586567764621299831222110000000"},"ep04_117":{"who":"RIN","text":"Then I'll hold it! Takuto, the bellows!","mono":false,"off":359.994,"dur":2.219,"env":"0499986798742389986178301102179501482427776266158665543321233200000"},"ep04_118":{"who":"RIN","text":"It broke the threads! Gideon, move!","mono":false,"off":362.6127,"dur":1.792,"env":"041018997010551013787663134102864666555555543321110000"},"ep04_119":{"who":"GIDEON","text":"My knee! I can't, my knee is fused! Bad joint!","mono":false,"off":364.8047,"dur":2.987,"env":"027998778996432135402268731245555565553331113554321111000000000000776542100226754111000000"},"ep04_120":{"who":"TAKUTO","text":"Get behind me!","mono":false,"off":368.1913,"dur":1.109,"env":"0049710096223676655433211100000000"},"ep04_121":{"who":"AKURO","text":"You spent it on the old man? Ha!","mono":true,"off":369.7007,"dur":2.091,"env":"023676442589854488646777778775366776544332000136886543211000000"},"ep04_122":{"who":"TAKUTO","text":"That's what it's for.","mono":false,"off":372.1913,"dur":1.152,"env":"00268713225986830321044432211000000"},"ep04_123":{"who":"GIDEON","text":"You... you used it on me.","mono":false,"off":373.7433,"dur":1.579,"env":"014898421000001332236643222024434665531111000000"},"ep04_124":{"who":"TAKUTO","text":"You built it. It's only fair.","mono":false,"off":375.722,"dur":1.685,"env":"002432299973025641001320454444331113443211100000000"},"ep04_125":{"who":"GIDEON","text":"Then let me return the favor. Cogwheel Core!","mono":false,"off":377.8073,"dur":2.795,"env":"026677895025653551032368744321115554211110000000000001368874201433210011454321100000"},"ep04_126":{"who":"GIDEON","text":"Every chain in this forge is mine! Bind it!","mono":false,"off":381.002,"dur":2.88,"env":"028932573002224787544444332210045433201233205676653211000000000000007865433321111000000"},"ep04_127":{"who":"WICK","text":"And burn it! Only it!","mono":false,"off":384.282,"dur":1.195,"env":"046419977777511266655544332202320000"},"ep04_128":{"who":"TAKUTO","text":"Ruinbreaker!","mono":false,"off":385.8767,"dur":0.981,"env":"013688877647986202553210000000"},"ep04_129":{"who":"RIN","text":"The Rift is closing.","mono":false,"off":387.258,"dur":1.28,"env":"045449751101563310126655422332222100000"},"ep04_130":{"who":"TAKUTO","text":"Something's on the other side of the smoke.","mono":false,"off":388.938,"dur":2.261,"env":"00149863017755542555455421376584232366544321132332155542100000000000"},"ep04_131":{"who":"SABLE","text":"Good catch.","mono":false,"off":391.5993,"dur":1.259,"env":"00111389731112334443101321000000000000"},"ep04_132":{"who":"RIN","text":"Who was that?! There was someone there, in a suit!","mono":false,"off":393.258,"dur":2.304,"env":"0076698320586654100005545332476666656545444443443222225432100100000000"},"ep04_133":{"who":"TAKUTO","text":"He was smiling.","mono":false,"off":395.962,"dur":1.045,"env":"00176594432799988653221110000000"},"ep04_134":{"who":"AKURO","text":"Static, boy. Didn't I tell you? He smells like static.","mono":true,"off":397.4073,"dur":3.883,"env":"012213888775642101368779887533676667677411124567655324432210000000245333323556766655432255531222213555554221100000000"},"ep04_135":{"who":"VALENTINE","text":"A Rift. Inside the walls of Ashford. Opened sideways, through a floor.","mono":false,"off":401.69,"dur":3.989,"env":"046434996300102003685342565530442355442241476423330012221000000000000588103676233325555521143222120003342000244432212100"},"ep04_136":{"who":"SIEG","text":"That's twice now. Once at the boy's crossing. Once here.","mono":false,"off":406.0793,"dur":3.52,"env":"0985133033876675317876656665100000069776532743776577667677640037876743276554310000001998874321786533210000"},"ep04_137":{"who":"GIDEON","text":"It was opened from this side. Like a door. Someone stood in my forge and turned a key.","mono":false,"off":409.9993,"dur":5.483,"env":"014324345788401133211133433311111343211010000000000002553124210466643210000000000000000002379876554422103652545544310001454322200100000232021465433121011123321100000"},"ep04_138":{"who":"TAKUTO","text":"There was a man. In a black suit. In the smoke. He said good catch.","mono":false,"off":415.882,"dur":3.797,"env":"004666487777788776543466315899740133346543000045655444306799742001000000000164339983212896201225763210012210000000"},"ep04_139":{"who":"SIEG","text":"...What did he look like?","mono":false,"off":420.0793,"dur":1.216,"env":"0499763376697777631038865553111100000"},"ep04_140":{"who":"TAKUTO","text":"I couldn't see a face. Just a grin. Like lightning. And one eye.","mono":false,"off":421.6953,"dur":3.947,"env":"00440298552433568211179642112222100000000000369440362112468776443344411134687641123322111344445444444443211100000000000"},"ep04_141":{"who":"VALENTINE","text":"Sieg. Say it.","mono":false,"off":426.042,"dur":1.365,"env":"00116777752254222499865543210100000000000"},"ep04_142":{"who":"SIEG","text":"Six years ago, my squad was holding the pass at Grey Hollow. The night before Morvudd came, a man walked into our camp.","mono":false,"off":427.8073,"dur":7.488,"env":"034951443597776576448766665200000577854500675555435665311686765777663002576555332363110488666666467566544322110000000000000079996653000386117777877666557654201188766665530000000005998866665677666310157742765520129754210000000"},"ep04_143":{"who":"SIEG","text":"Black suit. No face. He asked us which way the wind was blowing, and then he was gone.","mono":false,"off":435.6953,"dur":5.376,"env":"089752034338975411000007877751007776432333210000000000197676654300576533038523237766664665667665554457643206866665555554100000048988766776865664311775543322110000"},"ep04_144":{"who":"SIEG","text":"By morning there was a Rift above the pass, and I was the only one left.","mono":false,"off":441.4713,"dur":4.437,"env":"08878987776676666541000677866877778663110110006869865446510248766543343320000000004999777767764187200588777677666666666765431111010000"},"ep04_145":{"who":"TAKUTO","text":"You think it's the same man.","mono":false,"off":446.3087,"dur":1.621,"env":"0135410886239212103433236554444555432210000000000"},"ep04_146":{"who":"SIEG","text":"I think he opens doors for monsters. And I think he's interested in you.","mono":false,"off":448.33,"dur":4.373,"env":"069828863773037874106777653207866677653205888776655333016654433200000000000699988831296521598741048864339754006865777766655432210000"},"ep04_147":{"who":"GIDEON","text":"Then he made a mistake tonight. He showed us his face.","mono":false,"off":453.1033,"dur":3.093,"env":"026577677777725545421111005552000123342110000000000000003433339986323311102321100453210000000"},"ep04_148":{"who":"VALENTINE","text":"He showed us his grin, Gideon. That is not the same thing.","mono":false,"off":456.5967,"dur":3.221,"env":"0364555999927633203632102368777654314632333323310000000009951563458878400324325444430004433222000"},"ep04_149":{"who":"RIN","text":"What do we do?","mono":false,"off":460.218,"dur":0.917,"env":"0691379678427987544320000000"},"ep04_150":{"who":"SIEG","text":"We get stronger. Faster than he expects.","mono":false,"off":461.5353,"dur":2.496,"env":"089869521341169876677676565300000007976730297667789876423321187531013220000"},"ep04_151":{"who":"GIDEON","text":"And I rewind the chains. Tomorrow, boy, you'll have your one block again.","mono":false,"off":464.4313,"dur":4.544,"env":"03487776357534555443320201332454221100012100000000000002478998888553322100066653211000000000155233671134422555552145543210112113221000000"},"ep04_152":{"who":"TAKUTO","text":"Thanks, Gideon.","mono":false,"off":469.3753,"dur":1.045,"env":"00077654132113793433321110000000"},"ep04_153":{"who":"GIDEON","text":"Thank you. You spent it well.","mono":false,"off":470.8207,"dur":1.749,"env":"00189988511134321000000244332018953123201244421100000"},"ep04_154":{"who":"GIDEON","text":"Rewound. Tighter than before. You'll feel it pull when it locks.","mono":false,"off":472.97,"dur":3.84,"env":"01498489987532222100000002369984354314454241111465321000000000000001563327985740000147753334343201345542110002221000"},"ep04_155":{"who":"TAKUTO","text":"Your forge is gone, Gideon. You stayed up rewinding my chains?","mono":false,"off":477.21,"dur":4.032,"env":"0157511116789984133433211456666643332134222221110000000000033453069666498500045433554444333343333203314434211000011100000"},"ep04_156":{"who":"GIDEON","text":"An engineer without a forge is still an engineer. I did it on the fountain.","mono":false,"off":481.642,"dur":4.907,"env":"0146889885225466665433234246631121000045542211001000000001333320177446445555422234433211000000000000000013441028841321000145443111126643210101100000"},"ep04_157":{"who":"NEMU","text":"He did. The town guard tried to arrest him twice.","mono":false,"off":486.9487,"dur":3.648,"env":"00282469864321000000000000000000000522326899988733554332210000211566403334443355423213443203102432100023221000"},"ep04_158":{"who":"GIDEON","text":"And you, flame boy. Hold out your hands.","mono":false,"off":490.9967,"dur":2.624,"env":"0256446864211111358754444410465421100000000000005996516553012221244321100011000"},"ep04_159":{"who":"WICK","text":"Me? Why me?","mono":false,"off":494.0207,"dur":0.896,"env":"047667545897654422211110000"},"ep04_160":{"who":"GIDEON","text":"Gloves. Woven steel. Your fire obeys you, but your hands are still made of meat. These will hold heat, and throw it.","mono":false,"off":495.3167,"dur":7.531,"env":"0267997642111110024687412443222200343321100000000000000058321116777776545555311665554311112110000000023235322225665433322222220046544444442232034443100000000000000000047754331144311167754311000043100000000133111126764211000000"},"ep04_161":{"who":"WICK","text":"Throw it? I can THROW fire now?","mono":false,"off":503.2473,"dur":1.707,"env":"0037999899830057416763328763117876655654322111000000"},"ep04_162":{"who":"GIDEON","text":"You can aim it. Whether you hit anything is between you and your gods.","mono":false,"off":505.354,"dur":4.181,"env":"026404575677875221100000000000000049935653542127601257663100232212221003122045544432257643221000001342444201356542110000120000"},"ep04_163":{"who":"WICK","text":"Thank you! Thank you! Nobody ever gives me presents! I'll name them! Left one's Takoyaki!","mono":false,"off":509.9353,"dur":4.843,"env":"05876112775107776124886777889737967642595376316833336530127754343213430006777788777777644322210000000369951012667552337611486666775201110000000000"},"ep04_164":{"who":"GIDEON","text":"Please do not name the gloves.","mono":false,"off":515.178,"dur":1.963,"env":"01379853222122003766876542001356553322122002445421000011000"},"ep04_165":{"who":"WICK","text":"Right one's also Takoyaki.","mono":false,"off":517.5407,"dur":1.685,"env":"059964379875888744486322772138766666530112211100000"},"ep04_166":{"who":"GIDEON","text":"Thank you for the shield, boy. I meant it. I've built a thousand things. Nobody ever stood in front of me with one.","mono":false,"off":519.626,"dur":6.72,"env":"0048964111441123232211114554322211000355432110000000035544565412111000000000000000014531028853022210000555654322133200025432110011000000000000047994273443347413322103642433110157533102232122100232110000"},"ep04_167":{"who":"TAKUTO","text":"Build a thousand and one. I'll keep standing there.","mono":false,"off":526.746,"dur":2.965,"env":"03899627510067566664333433334344554211100000000166510112430134304445443333323221100000000"},"ep04_168":{"who":"NEMU","text":"The man in the suit. Rin told me.","mono":false,"off":530.1113,"dur":2.645,"env":"01244666665553324433343342642100030000000000000000039986540411254341101211000000"},"ep04_169":{"who":"TAKUTO","text":"Rin tells you everything.","mono":false,"off":533.1567,"dur":1.472,"env":"026888753469996445522586235400232110000000000"},"ep04_170":{"who":"NEMU","text":"Rin tells me nothing. I listen at doors.","mono":false,"off":535.0287,"dur":3.029,"env":"0079976542031134433204443332101211000000000000000000002675346322244330004343222100001322000"},"ep04_171":{"who":"NEMU","text":"I saw a man like that once. When I was little. Before my first life.","mono":false,"off":538.458,"dur":5.056,"env":"02535343877877767687887775544443010254400023221003333000000000000000000000000048899955763038934210000000000000004622598987741011776345201344422100010000"},"ep04_172":{"who":"TAKUTO","text":"Where?","mono":false,"off":543.914,"dur":0.619,"env":"0137899765432000000"},"ep04_173":{"who":"NEMU","text":"My village. He stood in the square and asked which way the wind was blowing. The next day, a Rift.","mono":false,"off":544.9327,"dur":7.787,"env":"001466201874432101333100000000000000000066530499389977543302566654433100000684327876413220021016215200467665550254216888654441024530234443221100000000000000000000000000000000000001477886002220246543211100000000000485226742110000002000"},"ep04_174":{"who":"NEMU","text":"That was the first time I died.","mono":false,"off":553.1193,"dur":1.92,"env":"0279630000486307211159973540422778864336630665321100001000"},"ep04_175":{"who":"TAKUTO","text":"...Nemu.","mono":false,"off":555.4393,"dur":0.853,"env":"01357998877787642110000000"},"ep04_176":{"who":"NEMU","text":"It's okay. It was a long time ago. I just... if he's looking at you, I don't want to die again for nothing.","mono":false,"off":556.6927,"dur":8.085,"env":"011143787303115542110000000000000000000000027427647644677788888734215676554023111100000000000000024640452432112241120000000000000000000000000051217553068122665543200113443210000000000000159499412677524220476555554420355443111355542101211000000"},"ep04_177":{"who":"TAKUTO","text":"You're not dying again. I'll break him first.","mono":false,"off":565.178,"dur":2.496,"env":"002667986212987766555421555422110000025784219872015531111776210244200000000"},"ep04_178":{"who":"NEMU","text":"You can't break everything, Takuto.","mono":false,"off":568.074,"dur":2.453,"env":"00412239963000026665102006951243100222210000000001326630105422413221100000"},"ep04_179":{"who":"TAKUTO","text":"Watch me.","mono":false,"off":570.9273,"dur":0.896,"env":"013799972152266442210000000"},"ep04_180":{"who":"NEMU","text":"...Mm. I'll watch.","mono":false,"off":572.2233,"dur":1.28,"env":"024987776654311015654213422110003432000"},"ep04_181":{"who":"RIN","text":"You didn't hesitate. With Gideon.","mono":false,"off":573.9033,"dur":1.792,"env":"036349677323488445403145552000265010168355443332100000"},"ep04_182":{"who":"TAKUTO","text":"Sieg told me what it was for.","mono":false,"off":576.0953,"dur":1.749,"env":"00122775310236996465544665422357634210232221000000000"},"ep04_183":{"who":"RIN","text":"My brother would have done the same thing.","mono":false,"off":578.2447,"dur":1.856,"env":"04788304999458874375631177666643443655654102533221000000"},"ep04_184":{"who":"TAKUTO","text":"Then I'm in good company.","mono":false,"off":580.5007,"dur":1.557,"env":"01765546886665554202898210225642024211000000000"},"ep04_185":{"who":"RIN","text":"...You're not him, you know.","mono":false,"off":582.458,"dur":1.28,"env":"023798998723257766334665554332100000000"},"ep04_186":{"who":"TAKUTO","text":"I know.","mono":false,"off":584.138,"dur":0.747,"env":"03677778999854210000000"},"ep04_187":{"who":"RIN","text":"He was taller.","mono":false,"off":585.2847,"dur":0.981,"env":"028769441233898876643321000000"},"ep04_188":{"who":"TAKUTO","text":"Of course he was.","mono":false,"off":586.666,"dur":1.173,"env":"132002178986322144334552211110000000"},"ep04_189":{"who":"RIN","text":"That man in the suit. If he comes after you, he comes after all of us.","mono":false,"off":588.2393,"dur":3.84,"env":"05884269988888746887634443786531021000000046118402389996398874102554555433520136666536653103655666551332122210000000"},"ep04_190":{"who":"TAKUTO","text":"Since when are you part of us?","mono":false,"off":592.4793,"dur":1.557,"env":"00249733137777766444112598755234211122100000000"},"ep04_191":{"who":"RIN","text":"Since I got commended for keeping you alive. I'm not letting you ruin my record.","mono":false,"off":594.4367,"dur":4.693,"env":"025587587882289820023889888746712223302215500556666687567655433321110000000168999998731458885767656653247887865554444542653001222102000000000"},"ep04_192":{"who":"AKURO","text":"She's fond of you, boy. Humans are so loud about it, even when they say nothing.","mono":true,"off":599.53,"dur":5.803,"env":"0024455643331137867787458622446533236999786543210000000124787879897643235543333577776563467777677554245544333432100000245556335766344543345432233334544333333443210122111000000"},"ep04_193":{"who":"TAKUTO","text":"...Shut up.","mono":false,"off":605.7327,"dur":0.811,"env":"0122337986976520011000000"},"ep04_194":{"who":"RIN","text":"What?","mono":false,"off":606.9433,"dur":0.555,"env":"03899852022431000"},"ep04_195":{"who":"TAKUTO","text":"Not you.","mono":false,"off":607.898,"dur":0.853,"env":"01468994013367753211100000"},"ep04_196":{"who":"SABLE","text":"He spent his one block on an old man. Sentimental.","mono":false,"off":609.1513,"dur":3.925,"env":"0000459627663222232124444322344553101223322232210133322212221000000000246545432223333321111111100000000000000000000000"},"ep04_197":{"who":"SABLE","text":"The Saint will want to meet him. Sooner than he planned.","mono":false,"off":613.4767,"dur":3.669,"env":"000156966665322111232235411224434311102222210000000013454454434332233322111243322211111000000000000000000000000"},"ep04_198":{"who":"TAKUTO","text":"Next time: the river town of Marrowmere.","mono":false,"off":617.546,"dur":2.368,"env":"024672154034777654331014238913611435444443421245444454322211000000000000"},"ep04_199":{"who":"TAKUTO","text":"There's a Hydra in the lake. Every head I cut off grows back.","mono":false,"off":620.314,"dur":3.712,"env":"0026755783222367777322453234544345553100000000000004794256644568555551011464555521000354443300554210000000000000"},"ep04_200":{"who":"TAKUTO","text":"Breaking a thing and killing it turn out to be different problems.","mono":false,"off":624.426,"dur":3.627,"env":"0058971136666511106866544321000244111179665444431001413655666520032133321551113200126767511221000012200000000"},"ep04_201":{"who":"TAKUTO","text":"Episode five. Seven Heads, One River.","mono":false,"off":628.4527,"dur":2.603,"env":"0461054446986311159776531100000012389824655335666421213444444454112210000000000"}}};
